import{_ as a,c as r,o as e,a0 as s}from"./chunks/framework.CAcMrZkh.js";const c=JSON.parse('{"title":"序言","description":"","frontmatter":{},"headers":[],"relativePath":"bearplan/first.md","filePath":"bearplan/first.md"}'),n={name:"bearplan/first.md"};function l(i,t,o,d,h,p){return e(),r("div",null,t[0]||(t[0]=[s(`<h1 id="序言" tabindex="-1">序言 <a class="header-anchor" href="#序言" aria-label="Permalink to &quot;序言&quot;">​</a></h1><blockquote><p>BearPlan 是一套面向中后台业务的全栈快速开发平台，目标是让开发者<strong>专注业务，不被基础设施拖累</strong>。</p></blockquote><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>BearPlan 是前后端分离、多端覆盖的开源开发平台：</p><ul><li><strong>后端</strong>：基于 .NET 10 + SqlSugar 的分层架构，内置权限、缓存、日志、AOP、定时任务、多租户等开箱能力。</li><li><strong>前端</strong>：基于 Vue 3 + Element Plus 的管理后台，配合 Alova.js 实现 API 自动集成。</li><li><strong>移动端</strong>：基于 Uni-App，一套代码编译到 H5、各平台小程序、App、鸿蒙。</li></ul><p>它不是「脚手架」，而是经过业务打磨的<strong>可演进基座</strong>——拿来即用，也能随业务自由扩展。</p><h2 id="为什么做" tabindex="-1">为什么做 <a class="header-anchor" href="#为什么做" aria-label="Permalink to &quot;为什么做&quot;">​</a></h2><p>市面上的 .NET 后台框架要么太重（绑定大量业务、难以裁剪），要么太轻（只给骨架、能力都要自己补）。BearPlan 的取舍是：</p><ul><li><strong>业务中立的核心库</strong>：把与业务无关的通用能力沉淀为独立的 <code>BearPlan.Core</code>，作为 NuGet 包或 Git Submodule 复用，不绑定任何业务实体。</li><li><strong>开箱即用的完整能力</strong>：权限、审计、缓存、多库、事件总线、定时任务等常用能力已内置并打通，开箱可跑。</li><li><strong>前后端 API 自动集成</strong>：基于 Swagger + Alova.js，后端接口变更前端自动同步，告别手写请求函数。</li></ul><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li>需要<strong>快速搭建中后台系统</strong>（OA / CRM / WMS / ERP 等）的团队。</li><li>想要一个<strong>可长期演进、不被业务绑死</strong>的 .NET 基座。</li><li>希望前后端<strong>高效协同</strong>，减少接口对接成本的开发者。</li></ul><p>如果你只是想要一个纯前端模板，或一个不含任何框架封装的极简后端，BearPlan 可能偏重——它面向的是「正经业务系统」。</p><h2 id="技术栈速览" tabindex="-1">技术栈速览 <a class="header-anchor" href="#技术栈速览" aria-label="Permalink to &quot;技术栈速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>技术</th></tr></thead><tbody><tr><td><strong>后端运行时</strong></td><td>.NET 10</td></tr><tr><td><strong>ORM</strong></td><td>SqlSugarCore（支持 MySQL / SQL Server / PostgreSQL / Oracle / SQLite）</td></tr><tr><td><strong>缓存</strong></td><td>StackExchange.Redis</td></tr><tr><td><strong>日志</strong></td><td>Serilog</td></tr><tr><td><strong>依赖注入 / AOP</strong></td><td>Autofac（含 DynamicProxy）</td></tr><tr><td><strong>前端框架</strong></td><td>Vue 3.5+ / TypeScript</td></tr><tr><td><strong>前端 UI</strong></td><td>Element Plus（基于 SoybeanAdmin）</td></tr><tr><td><strong>请求层</strong></td><td><a href="https://alova.js.org/" target="_blank" rel="noreferrer">Alova.js</a></td></tr><tr><td><strong>移动端</strong></td><td>Uni-App</td></tr></tbody></table><p>更多细节见 <a href="/bearplan/dotnet.html">框架介绍</a>。</p><h2 id="如何开始" tabindex="-1">如何开始 <a class="header-anchor" href="#如何开始" aria-label="Permalink to &quot;如何开始&quot;">​</a></h2><ol><li><p><strong>了解整体架构</strong>：阅读 <a href="/bearplan/dotnet.html">框架介绍</a>，理解分层与依赖方向。</p></li><li><p><strong>拉取项目</strong>：主项目通过 Git Submodule 引入 Core：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆时一并拉取子模块</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://gitee.com/BearPlan/BearPlan.NET.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或已克隆的仓库补充拉取</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span></code></pre></div></li><li><p><strong>启动运行</strong>：默认账号 <code>admin / 123456</code>。</p></li><li><p><strong>部署上线</strong>：参考 <a href="/bearplan/deploy.html">部署总览</a>，按端选择部署方式。</p></li></ol><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="/bearplan/dotnet.html">框架介绍</a></td><td>整体架构、分层职责、依赖关系</td></tr><tr><td><a href="/bearplan/introduction.html">BearPlan.Core 介绍</a></td><td>通用核心库的能力清单</td></tr><tr><td><a href="/bearplan/quickstart.html">快速开始</a></td><td>Core 的两种引入方式（Submodule / NuGet）</td></tr><tr><td><a href="/bearplan/deploy.html">部署总览</a></td><td>前端、后端、移动端的部署方式</td></tr></tbody></table><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li><strong>主项目仓库</strong>：<a href="https://gitee.com/BearPlan/BearPlan.NET" target="_blank" rel="noreferrer">https://gitee.com/BearPlan/BearPlan.NET</a></li><li><strong>Core 独立仓库</strong>：<a href="https://gitee.com/BearPlan/BearPlan.NET.Core" target="_blank" rel="noreferrer">https://gitee.com/BearPlan/BearPlan.NET.Core</a></li><li><strong>开发文档</strong>：<a href="https://bear.js.org/" target="_blank" rel="noreferrer">https://bear.js.org/</a></li><li><strong>作者微信</strong>：Byte_Xiong（备注：框架）</li></ul><hr><p>集百家之所长，千家之所强。BearPlan 站在 <a href="https://docs.soybeanjs.cn/" target="_blank" rel="noreferrer">SoybeanAdmin</a>、<a href="https://alova.js.org/zh-CN/" target="_blank" rel="noreferrer">Alova.js</a>、SqlSugar 等优秀开源项目肩上，向它们致敬。</p>`,23)]))}const b=a(n,[["render",l]]);export{c as __pageData,b as default};
